//! Fine angle tables and the binary angle measurement (BAM) type, ported
//! from the original `tables.c`/`tables.h`.
//!
//! Table values are exact copies of the original engine's tables, extracted
//! directly from the original engine constants. Do not hand-edit them; the
//! exact values matter for determinism.
//!
//! [`Angle`](crate::tables::Angle) wraps a `u32` BAM: a full circle is 2^32, so 2 * [`Angle::ANG180`](crate::tables::Angle::ANG180)
//! wraps back to zero and angle math can use plain wrapping `u32` arithmetic.

use core::fmt;
use core::ops;

use crate::fixed::Fixed;

/// Number of fine angles in a full circle (8192).
pub const FINE_ANGLES: usize = 8192;
/// Mask for fine angle indices (`FINE_ANGLES - 1`).
pub const FINE_MASK: u32 = FINE_ANGLES as u32 - 1;
/// Shift from a 32-bit BAM angle to a fine angle index (19).
pub const ANGLE_TO_FINE_SHIFT: u32 = 19;

/// Binary Angle Measurement: a `u32` where 0 and 2^32 are the same angle.
///
/// Adding and subtracting angles wraps, matching the original engine.
/// Comparisons are raw bit comparisons; there is no meaningful rotation
/// order on a circle, so [`Ord`] is intentionally not implemented.
#[derive(Clone, Copy, Default, PartialEq, Eq, Hash)]
pub struct Angle(u32);

impl Angle {
    /// Zero degrees.
    pub const ZERO: Angle = Angle(0);
    /// 45 degrees (0x20000000).
    pub const ANG45: Angle = Angle(0x2000_0000);
    /// 90 degrees (0x40000000).
    pub const ANG90: Angle = Angle(0x4000_0000);
    /// 180 degrees (0x80000000).
    pub const ANG180: Angle = Angle(0x8000_0000);
    /// 270 degrees (0xc0000000).
    pub const ANG270: Angle = Angle(0xC000_0000);

    /// Wraps a raw BAM value.
    pub const fn from_raw(raw: u32) -> Self {
        Angle(raw)
    }

    /// Returns the raw BAM value.
    pub const fn to_raw(self) -> u32 {
        self.0
    }

    /// Fine table index for this angle: `angle >> ANGLE_TO_FINE_SHIFT`.
    /// The result is in `0..FINE_ANGLES`.
    pub const fn fine_angle(self) -> usize {
        (self.0 >> ANGLE_TO_FINE_SHIFT) as usize
    }

    /// Angle in degrees, for debugging and display only.
    pub fn degrees(self) -> f64 {
        f64::from(self.0) * 360.0 / 4_294_967_296.0
    }
}

impl ops::Add for Angle {
    type Output = Angle;

    fn add(self, rhs: Self) -> Self {
        Angle(self.0.wrapping_add(rhs.0))
    }
}

impl ops::Sub for Angle {
    type Output = Angle;

    fn sub(self, rhs: Self) -> Self {
        Angle(self.0.wrapping_sub(rhs.0))
    }
}

impl ops::AddAssign for Angle {
    fn add_assign(&mut self, rhs: Self) {
        *self = *self + rhs;
    }
}

impl ops::SubAssign for Angle {
    fn sub_assign(&mut self, rhs: Self) {
        *self = *self - rhs;
    }
}

impl fmt::Display for Angle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:.3}°", self.degrees())
    }
}

impl fmt::Debug for Angle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Angle({self})")
    }
}

