#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sine_zero_is_tiny_positive() {
        assert_eq!(FINE_SINE[0], Fixed::from_raw(25));
    }

    #[test]
    fn sine_at_90_is_one_approx() {
        let one = FINE_SINE[Angle::ANG90.fine_angle()];
        assert!((one - Fixed::ONE).abs() <= Fixed::from_raw(2));
    }

    #[test]
    fn cosine_matches_shifted_sine() {
        for i in 0..8192 {
            assert_eq!(FINE_COSINE[i], FINE_SINE[i + FINE_ANGLES / 4]);
        }
    }

    #[test]
    fn sine_is_antisymmetric_around_half_circle() {
        // the literal table wobbles by one raw step here and there, so allow 1
        for i in 0..FINE_SINE.len() - FINE_ANGLES / 2 {
            let sum = FINE_SINE[i + FINE_ANGLES / 2] + FINE_SINE[i];
            assert!(sum.abs() <= Fixed::from_raw(1), "antisymmetry off at {i}");
        }
    }

    #[test]
    fn tangent_is_antisymmetric_around_center() {
        for j in 0..FINE_TANGENT.len() / 2 - 1 {
            assert_eq!(FINE_TANGENT[2048 - 1 - j], -FINE_TANGENT[2048 + j]);
        }
    }

    #[test]
    fn cosine_at_zero_is_one_approx() {
        assert!((FINE_COSINE[0] - Fixed::ONE).abs() <= Fixed::from_raw(2));
    }

    #[test]
    fn angle_constants_match_bam_layout() {
        assert_eq!(Angle::ANG45.to_raw(), 0x2000_0000);
        assert_eq!(Angle::ANG90.to_raw(), 0x4000_0000);
        assert_eq!(Angle::ANG180.to_raw(), 0x8000_0000);
        assert_eq!(Angle::ANG270.to_raw(), 0xC000_0000);
        assert_eq!(Angle::ANG90 + Angle::ANG90, Angle::ANG180);
        assert_eq!(Angle::ANG180 + Angle::ANG180, Angle::ZERO);
    }

    #[test]
    fn fine_angle_uses_angle_to_fine_shift() {
        assert_eq!(ANGLE_TO_FINE_SHIFT, 19);
        assert_eq!(Angle::ANG90.fine_angle(), 2048);
        assert_eq!(Angle::ANG180.fine_angle(), 4096);
        assert_eq!(Angle::from_raw(u32::MAX).fine_angle(), 8191);
        assert_eq!(Angle::ZERO.fine_angle(), 0);
    }

    #[test]
    fn angles_wrap_on_add_sub() {
        assert_eq!(Angle::from_raw(u32::MAX) + Angle::from_raw(1), Angle::ZERO);
        assert_eq!(Angle::ZERO - Angle::from_raw(1), Angle::from_raw(u32::MAX));
    }

    #[test]
    fn degrees_helper() {
        assert_eq!(Angle::ANG90.degrees(), 90.0);
        assert_eq!(Angle::ANG180.degrees(), 180.0);
        assert_eq!(Angle::ZERO.degrees(), 0.0);
    }

    #[test]
    fn display_and_debug() {
        assert_eq!(Angle::ANG90.to_string(), "90.000°");
        assert_eq!(format!("{:?}", Angle::ANG90), "Angle(90.000°)");
    }
}
